'use strict';
const fieldGuideGroups=[
 {id:'rules',title:'高尔夫规则',subtitle:'懂一点规则，下场更从容。',icon:'book',kicker:'在规则里，安心挥杆',intro:'从常遇到的情况开始，读懂球场，也读懂这一杆。',articles:[
  {id:'spirit',title:'从这三件小事开始',summary:'诚实、尊重，以及原位打球',lead:'高尔夫的从容，来自对自己和球场的尊重。',sections:[['记住三个原则',['按球场现状打球，按球的原位打球；规则允许的补救另论。','诚实记录成绩，并对自己的规则责任负责。','照顾同组球友，也照顾留下来的每一片草地。']]],source:1},
  {id:'lost',title:'球找不到，或打出界了',summary:'找球时间、杆数与距离处罚',lead:'先确认球的状态，再决定下一步。',sections:[['先分清是哪一种情况',['开始找球后，通常有 3 分钟的找球时间。','球遗失在罚杆区外或出界，通常罚一杆，并回上一杆的位置重新打球。','若球可能在罚杆区外遗失或出界，可按规则先打暂定球，并先说明。']],['一个容易混淆的地方',['出界与罚杆区不是同一件事。不要自行按“落点附近加一杆”处理；特殊替代方式须由当地规则明确采用。']]],source:18},
  {id:'penalty-area',title:'看懂红桩与黄桩',summary:'罚杆区的基本处理',lead:'水边很美，选补救方式时也值得慢一点。',sections:[['常见选择',['在规则允许且安全的情况下，可在罚杆区按原位打球。','接受罚杆区补救，通常罚一杆，可选择杆数与距离或后方线上补救。','红色罚杆区还可选择侧方补救：以最后越过边界处为参考点，两支球杆长度内，不得更靠近球洞。黄色罚杆区不自动有这一选择。']],['先确认再打',['球是否在罚杆区、最后越界的位置、禁打区和当地规则，都会影响具体处理。']]],source:17},
  {id:'green',title:'到了果岭，轻一点',summary:'标记球位、修球痕与旗杆',lead:'一张平整的果岭，值得被温柔对待。',sections:[['可以这样做',['在果岭上拿起球清洁前，先标记位置，随后按规则放回原位。','可以按规则修复球痕等允许修复的损伤，避免损坏果岭。','可以选择把旗杆留在洞内推球；不要为了影响运动中的球而移动旗杆。']]],source:13},
  {id:'score',title:'在青野里，怎样记这一杆',summary:'总杆、推杆和罚杆之间的关系',lead:'把记录交给工具，把注意力留给眼前。',sections:[['先记实际发生的事',['本洞总杆应包含罚杆。详细记录里的推杆和罚杆，是总杆的组成部分，不会再重复加一次。','例如实际击球 5 次、罚 1 杆，本洞总杆填 6，罚杆填 1。','捡球、跳洞和比洞中的认可，需要选对应状态；空白球洞不会当作 0 杆。']],['让杆是另一层计算',['净杆只用于约定的比赛比较，不覆盖你的实际杆数。开局前与球友确认玩法和让杆即可。']]],local:true}
 ]},
 {id:'formats',title:'高尔夫玩法',subtitle:'给同一片球场，多一点相伴的乐趣。',icon:'flag',kicker:'今天，想怎样一起玩',intro:'先聊好约定，再一起出发。以下说明对应青野当前支持的玩法。',articles:[
  {id:'record',title:'仅记分 · 自己的节奏',summary:'1–4 人，各自记录，不设主赛排名',lead:'有时候，能走在球场上，就是今天最好的收获。',sections:[['适合什么时候',['初次下场、轻松练习，或只想记录一段球场时光。','每位球友各记各的实际杆数，不必设置主赛和让杆。']],['在青野里',['创建对局时选择“仅记分”，确认球场、洞段和发球台即可。']]],local:true},
  {id:'stroke',title:'比杆 · 看完整段旅程',summary:'累计成绩，较低者领先',lead:'每一洞的起伏，最后都汇成这一轮的故事。',sections:[['怎样比较',['常规比杆累计约定球洞的杆数，较低者领先；比净杆须先明确让杆。','正式常规比杆需要实际完成各洞。缺洞或捡球不能自行补作 Par 或 0 杆。']],['在青野里',['“个人比杆”默认使用总杆；若选择封顶等自定义方式，应在出发前说明，结果会与原始实际成绩分开展示。']]],source:3},
  {id:'match',title:'比洞 · 每一洞重新期待',summary:'两位球友，逐洞比较胜平负',lead:'上一洞的遗憾，可以留在上一洞。',sections:[['怎样比较',['每洞较低的适用杆数赢一洞，相同为平；最终看洞数领先。','比洞可由对手认可下一杆、让洞或认输；认可与实际推进是不同的记录。']],['在青野里',['两人可选“两人比洞”；需要净杆时先约定让杆。只记录“捡球”，不会自动判对手赢洞。']]],source:3},
  {id:'fourball',title:'四球 · 与队友并肩',summary:'四人两队，各自打球，取队内较好成绩',lead:'有人和你一起期待下一杆，是另一种好风景。',sections:[['怎样比较',['两人一队，每个人打自己的球。比杆或比洞时，每洞取队内较低的适用杆数，不把两人杆数相加。']],['在青野里',['选择“四人两队比洞”，确认队伍。若采用积分赛，每洞取队内较高积分。未录入的队友不等于自动放弃，按实际情况补记录或明确状态。']]],source:23},
  {id:'points',title:'8421 · 留住好球的惊喜',summary:'按相对 Par 换算积分，累计比较',lead:'一记好球，会以另一种方式留下来。',sections:[['青野当前的积分表',['Eagle 8 分，Birdie 4 分，Par 2 分，Bogey 1 分；高于 Par 两杆及以上 0 分。','低于 Par 三杆及更好，产品预设统一 16 分。需要净杆积分时，先配置让杆。']],['记得提前说清楚',['这是一张产品预设积分表，不是按球友名次分配“8、4、2、1”。空白或跳洞保持待确认，明确捡球按对应积分状态处理。']]],local:true},
  {id:'sidegames',title:'Skins 与拿骚 · 多一点小乐趣',summary:'附加玩法独立计算，不覆盖实际杆数',lead:'好的约定，让一场友谊局多一点笑声。',sections:[['Skins 抢洞',['2–4 人，每洞独自最低者获得点数。并列时可约定滚入下一洞或当洞不滚存。','青野支持个人仅记分、常规比杆或积分赛中启用；不用于比洞或封顶比杆。']],['拿骚',['把前九、后九和全场视作三场独立比洞。青野当前用于按第 1 洞顺序开始的 18 洞比洞，可选两人或四人两队。','产品默认每项胜得 1 分、平各 0.5 分；不涉及金额，也不自动加注。']],['出发前，一起确认',['选择“修改规则”查看附加玩法。把并列、让杆和缺洞处理说清楚，打起来才更轻松。']]],local:true}
 ]},
 {id:'etiquette',title:'下场小贴士',subtitle:'让自己舒服，也让同伴舒服。',icon:'leaf',kicker:'把温柔，也带进球场',intro:'有些好体验，来自彼此照顾的细节。',articles:[
  {id:'company',title:'把安静，留给正在挥杆的人',summary:'站位、声音与同组相处',lead:'一段舒服的球场时光，往往从体谅开始。',sections:[['给彼此一点空间',['别人准备击球时，保持安静，避免在其视线附近走动。','先确认前方球友已离开可能的击球范围；等待时可以提前准备下一杆。','尊重球场工作人员，也尊重每位球友自己的节奏。']]],source:1},
  {id:'pace',title:'从容，也照顾整组的节奏',summary:'提前准备，顺畅前行',lead:'慢下来感受风景，打球时也让整组顺畅。',sections:[['把准备放在等待里',['提前想好球杆、距离与击球计划，轮到自己时及时打球。','跟上前组，遵守球场的打球速度安排。安全且合适时，常规比杆可采用准备好先打的方式；比洞的打球顺序另有规则。']]],source:5},
  {id:'care',title:'把好风景，留给下一组',summary:'修复球痕，照顾球场',lead:'我们只是经过，也可以留下温柔的痕迹。',sections:[['走过之后',['按球会要求修复打痕、平整沙坑，修补允许修复的果岭球痕。','球车行驶、草地养护和临时禁行要求，以当天球场安排为准。','把随身物品和垃圾带走，把绿色留在原处。']]],source:1}
 ]}
];
function fieldGuideGroup(){return fieldGuideGroups.find(g=>g.id===route.id);}
function golfGuidePage(){
 const group=fieldGuideGroup();if(!group)return empty('这页小册还没收录','回到记分入口，慢慢翻翻其他内容。','play','返回记分');
 const slug=route.q.get('topic'),article=group.articles.find(a=>a.id===slug);
 if(slug&&!article)return empty('这篇内容暂未收录','可以返回目录查看其他主题。','guide/'+group.id,'返回目录');
 if(!article)return `<section class="guide-intro"><span class="guide-quiet-icon">${icon(group.icon)}</span><p class="guide-kicker">${group.kicker}</p><h1>${group.title}</h1><p>${group.intro}</p></section><div class="guide-topic-list">${group.articles.map((a,i)=>go('guide/'+group.id+'?topic='+a.id,`<span class="guide-topic-number">${String(i+1).padStart(2,'0')}</span><span><b>${esc(a.title)}</b><small>${esc(a.summary)}</small></span>${icon('chevron')}`,'guide-topic')).join('')}</div><p class="guide-footnote">${group.id==='rules'?'入门速览，正式比赛以现行规则和球场当地规则为准。':group.id==='formats'?'说明对应当前产品设置；每场玩法，以同组确认的规则为准。':'把这些小细节，带进下一段球场时光。'}</p>`;
 return `<article class="guide-article"><div class="guide-article-header"><p class="guide-kicker">${group.title}</p><h1>${esc(article.title)}</h1><p>${esc(article.lead)}</p></div>${article.sections.map(([heading,paragraphs])=>`<section><h2>${esc(heading)}</h2>${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}<div class="guide-reading-note">${article.local?'以上为青野当前产品玩法或录入说明。每场球以你们确认的设置为准。':'这是便于下场前阅读的要点，不涵盖所有例外。遇到具体情况，请结合现行规则、当地规则及裁判意见。'}</div>${article.source?`<details class="guide-source"><summary>规则依据与更新时间</summary><p>依据 R&amp;A 现行规则公开说明整理 · 核对于 2026-10-24。</p><a href="https://www.randa.org/en/rog/the-rules-of-golf/rule-${article.source}" target="_blank" rel="noopener noreferrer">R&amp;A · Rule ${article.source} 官方原文 ${icon('arrow')}</a></details>`:''}<div class="guide-ending"><p>读完这一页，去遇见下一阵风。</p>${go('guide/'+group.id,'返回目录','btn outline')}${go('courses?select=1','选个球场，去走走 '+icon('arrow'),'btn primary')}</div></article>`;
}
play=function(){
 const a=active(),paused=db.rounds.filter(r=>r.status==='paused').sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
 return `<div class="lounge-welcome"><span>此刻，在青野</span><p>今天，把节奏交给自己。</p></div><figure class="retreat-hero"><img src="assets/share/morning-fairway-original.png" alt="晨光、湖面与球道的青野 AI 意境图"><figcaption><h1>走进绿意，<br>把心放慢。</h1><p>沿着球道走一走，让呼吸慢下来。</p></figcaption><span class="retreat-image-credit">AI 意境</span></figure><section class="lounge-start">${a?`<div class="lounge-round"><span class="lounge-round-dot"></span><div><small>继续今天的球场时光</small><h2>${esc(a.courseName)}</h2><p>第 ${a.currentHole} 洞 · ${a.holes.length} 洞 · ${a.players.length} 位球友</p></div></div>`:''}${action(a?'resume':'start',(a?'继续本轮记分':'开始一场好球')+' '+icon('arrow'),'btn primary full lounge-primary',a?`data-id="${esc(a.id)}"`:'')}${a?action('start',icon('plus')+' 选个球场，开启新一场','lounge-new'):go('courses','先看看，下一段风景在哪里 '+icon('chevron'),'lounge-new')}</section><section class="lounge-library"><div class="lounge-section-title"><h2>下场前，随手翻翻</h2><span>一会儿就好</span></div><div class="lounge-menu-list">${fieldGuideGroups.map(g=>go('guide/'+g.id,`<span class="lounge-menu-icon">${icon(g.icon)}</span><span class="lounge-menu-copy"><b>${g.title}</b><small>${g.subtitle}</small></span>${icon('chevron')}`,'lounge-menu')).join('')}</div></section><details class="lounge-paused"><summary><span>${icon('history')} 暂存的球局</span><span>${paused.length?paused.length+' 场待续':'随时可以回来'}${icon('chevron')}</span></summary><div>${paused.length?paused.map(r=>`<article class="lounge-paused-round"><h3>${esc(r.courseName)}</h3><p>${esc(r.date)} · ${r.players.length} 人 · 已记录 ${G.summary(r,'me').played}/${r.holes.length} 洞</p><div>${go('result/'+r.id,'查看记录','text-link')}${action('resume','继续记分 '+icon('arrow'),'btn secondary',`data-id="${esc(r.id)}"`)}</div></article>`).join(''):'<p class="lounge-paused-empty">还没有待续的球局。今天，就从一段新风景开始。</p>'}</div></details><div class="lounge-signoff">${icon('leaf')}<p>一场好球之外，还有一整天好心情。</p><small>每次有效记分会自动保存到当前浏览器。</small></div>`;
};
const retreatHome=home;home=function(){return retreatHome().replace('<h1>去球场，找回好状态</h1>','<h1>把好时光，留在球场。</h1>').replace('今天也为热爱挥杆。','沿着绿色，慢慢找回自己。').replace('<div class="hero">'+img(),'<div class="hero home-retreat-hero"><img src="assets/share/morning-fairway-original.png" alt="晨光湖畔的青野 AI 球场意境图">').replace('A GOOD DAY FOR GOLF','青野 · AI 意境').replace('LESS DISTRACTION. MORE GOLF.','走进这一程绿色').replace('下一杆，值得期待。','与自己，慢慢相逢。').replace('让每一次挥杆，都有迹可循。','风经过球道，也经过心里。');};
const retreatCourses=coursesPage;coursesPage=function(){return retreatCourses().replace('把全国球场，装进口袋。','下一段风景，慢慢选。').replace('选一座城市，开启下一场好球','选一座城市，去遇见一片新的绿意');};
const guideActions=handleAction;handleAction=async function(el,event){if(el.dataset.action==='back'&&route.name==='guide'){nav(route.q.has('topic')?'guide/'+route.id:'play');return;}return guideActions(el,event);};
const guideRender=render;render=function(){guideRender();document.body.classList.toggle('at-the-lounge',route.name==='play');document.body.classList.toggle('reading-field-guide',route.name==='guide');if(route.name==='guide')document.title='青野 · '+(fieldGuideGroup()?.title||'球场小册');};
render();
